export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>millis(v)?new Date(millis(v)).toLocaleDateString('zh-TW',{timeZone:'Asia/Taipei'}):'尚無紀錄';
const ago=v=>daysSince(v)===null?'尚無紀錄':daysSince(v)===0?'今天':daysSince(v)+' 天前';
