 const previewCache=new Map();
 async function previewRoom(u){if(!admin||!u)return;const d=modal(u.name||'訊息預覽','<p class="previewHint">預覽模式 · 不會標記已讀</p><div class="previewMessages" role="log"><p>讀取近期訊息…</p></div><button class="previewEnter">進入對話並標記已讀</button>');d.classList.add('chatPreview');d.querySelector('.previewEnter').onclick=()=>{d.close();demo?demoChat(sample):openChat(u.id);};try{const rows=demo?[{senderRole:'customer',text:'您好，請問明天下午可以剪髮嗎？'}]:await readPreview({room:u.id,cache:previewCache,read:async(room,n)=>{const q=query(collection(db,'chats',room,'messages'),orderBy('createdAt','desc'),limit(n));const snap=await getDocsFromServer(q);return snap.docs.map(x=>x.data()).reverse();}});if(!d.isConnected)return;const box=d.querySelector('.previewMessages');box.innerHTML=rows.map(m=>`<div class="previewBubble ${m.senderRole==='admin'?'mine':''}">${esc(m.retracted?'訊息已收回':m.sticker?'［貼圖］':m.attachment?'［附件］ '+(m.attachment.name||''):m.text)}<small>${millis(m.createdAt)?new Date(millis(m.createdAt)).toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit'}):''}</small></div>`).join('')||'<p>尚無訊息</p>';box.scrollTop=box.scrollHeight;}catch(e){if(d.isConnected)d.querySelector('.previewMessages').textContent='暫時無法載入預覽，請稍後再試。';}}
 async function approvalPage(body){const snap=await getDocsFromServer(query(collection(db,'users'),where('status','==','pending'),limit(100)));const rows=snap.docs.map(d=>({id:d.id,...d.data()}));body.innerHTML='<p>核對姓名與電話後再核准；相同姓名不代表同一個人。</p>'+rows.map(u=>`<article class="settingsGroup"><b>${esc(u.name)}</b><p>${esc(u.phone)}</p><button data-approve="${esc(u.id)}">核准加入</button><button data-reject="${esc(u.id)}" class="softBtn">拒絕</button></article>`).join('')+(rows.length?'':'<p>目前沒有待核准申請。</p>');for(const b of body.querySelectorAll('[data-approve],[data-reject]'))task(b,async()=>{const id=b.dataset.approve||b.dataset.reject,u=rows.find(x=>x.id===id),status=b.dataset.approve?'active':'revoked';if(!await confirmAction(b.dataset.approve?'核准這位客人？':'拒絕這位客人？',u.name+' · '+u.phone))return;const batch=writeBatch(db);batch.set(doc(db,'users',id),{status,updatedAt:stamp()},{merge:true});batch.set(doc(db,'chats',id),{userId:id,name:u.name||'',phone:u.phone||'',status,updatedAt:stamp()},{merge:true});await batch.commit();customersAt=0;await approvalPage(body);toast('帳號狀態已更新');});}
 async function markRoomRead(u){if(demo){u.readAdminMs=millis(u.lastCustomerMessageAt);renderInbox([{id:u.id,data:()=>u}]);toast('範例已標記已讀');return;}await runTransaction(db,async tx=>{const ref=doc(db,'chats',u.id),snap=await tx.get(ref),x=snap.data()||{},value=millis(x.lastCustomerMessageAt);if(value>Number(x.readAdminMs||0))tx.update(ref,{readAdminMs:value});});toast('已標記已讀');}
 function roomMenu(u){const d=modal(u.name||'對話選項',`<div class="roundActions"><button id="roomPending">${icon('clock')}<span>${u.needsReply?'取消待處理':'稍後處理'}</span></button><button id="roomRead">${icon('check')}<span>標記已讀</span></button><button id="roomBlock">${icon('block')}<span>${u.status==='blocked'?'解除封鎖':'封鎖顧客'}</span></button><button id="roomArchive">${icon('archive')}<span>${u.adminArchived?'恢復對話':'移至封存'}</span></button><button id="roomProfile">${icon('person')}<span>顧客資料</span></button></div><p class="small">封存只收起店家端對話，不刪除聊天內容；可從封存對話恢復。</p>`);task($('roomPending'),async()=>{await store('chats/'+u.id,{needsReply:!u.needsReply});d.close();toast('待處理狀態已更新');});task($('roomRead'),async()=>{await markRoomRead(u);d.close();});task($('roomArchive'),async()=>{if(!demo)await store('chats/'+u.id,{adminArchived:!u.adminArchived});else{u.adminArchived=!u.adminArchived;renderInbox([{id:u.id,data:()=>u}]);}d.close();toast('對話封存狀態已更新');});task($('roomBlock'),async()=>{const status=u.status==='blocked'?'active':'blocked';d.close();if(!await confirmAction(status==='blocked'?'封鎖這位顧客？':'解除封鎖？','封鎖後此顧客將無法傳送新訊息或預約。'))return;if(demo){u.status=status;renderInbox([{id:u.id,data:()=>u}]);}else{const batch=writeBatch(db);batch.set(doc(db,'users',u.id),{status,updatedAt:stamp()},{merge:true});batch.set(doc(db,'chats',u.id),{status},{merge:true});await batch.commit();}customersAt=0;toast('已更新顧客狀態');});task($('roomProfile'),async()=>{d.close();const data=demo?sample:(await getDocFromServer(doc(db,'users',u.id))).data();if(!data)throw Error('找不到顧客資料');await editCustomer({id:u.id,...data});});}
 function polishIcons(){document.querySelectorAll('.profileSwitch [data-header-page=info]').forEach(b=>{if(!b.querySelector('svg'))b.innerHTML=icon('home');});document.querySelectorAll('.headerActions [data-header-page]').forEach(b=>{if(!b.querySelector('svg'))b.innerHTML=icon(b.dataset.headerPage==='preferences'?'settings':'home');});const map={approvals:'person',feedback:'chat',broadcast:'send',welcome:'heart',autoreply:'reply',notice:'calendar',gallery:'image',customers:'people',tags:'tag',theme:'image',stickers:'heart',settings:'settings',board:'board',booking:'calendar',automation:'clock'};document.querySelectorAll('[data-tool]').forEach(b=>{const span=b.querySelector('span');if(span)span.innerHTML=icon(map[b.dataset.tool]);});document.querySelectorAll('[data-customer-page],[data-admin-page]').forEach(b=>{const id=b.dataset.customerPage||b.dataset.adminPage,key={inbox:'chat',booking:'calendar',info:'home',gallery:'image',preferences:'settings',profile:'person',adminHome:'home',admin:'chat',adminAnalysis:'chart'}[id];if(!key)return;const span=b.querySelector('span');if(span)span.innerHTML=icon(key);else b.innerHTML=icon(key);});document.querySelectorAll('.bottomNav').forEach(nav=>{const tabs=[...nav.querySelectorAll('.navBtn')];nav.style.setProperty('--tabs',tabs.length);nav.style.setProperty('--nav-index',Math.max(0,tabs.findIndex(b=>b.classList.contains('active'))));});document.querySelectorAll('.infoActions a,.infoActions button').forEach(b=>{const label=b.textContent.replace(/[☏⌖▧]/g,'').trim();b.innerHTML=icon(b.id==='infoProducts'?'image':b.getAttribute('href')?.startsWith('tel:')?'phone':'pin')+'<span>'+esc(label)+'</span>';});}
 function organizeAdmin(){document.body.classList.add('adminApp');const grid=document.querySelector('.toolGrid'),groups=[['日常接待',['customers','booking','tags','approvals']],['訊息與關懷',['broadcast','autoreply','welcome','automation']],['店面與展示',['board','gallery','notice','theme','feedback','settings']]];const buttons=new Map([...grid.querySelectorAll('[data-tool]')].map(b=>[b.dataset.tool,b]));grid.replaceChildren();for(const [title,keys]of groups){const section=document.createElement('section');section.className='toolGroup';const h=document.createElement('h3');h.textContent=title;section.append(h);const cells=document.createElement('div');cells.className='toolCells';keys.forEach(k=>{if(buttons.has(k))cells.append(buttons.get(k));});section.append(cells);grid.append(section);}const share=document.createElement('a');share.className='menuCard';share.href='./join.html';share.target='_blank';share.rel='noopener';share.className='menuCard inviteCard';share.innerHTML=icon('people')+'<span><b>邀請客人加入</b><small>開啟 QR 碼・分享網址・列印</small></span><span>›</span>';const labels={tags:'標籤庫',autoreply:'快捷詢問・自動回覆',settings:'店家資訊・預約設定'};grid.querySelectorAll('[data-tool]').forEach(b=>{if(labels[b.dataset.tool])b.querySelector('b').textContent=labels[b.dataset.tool];});grid.append(share);document.querySelector('.shopHeader').onclick=()=>ctx.openTool('settings');document.querySelector('.shopHeader').setAttribute('role','button');document.querySelector('.shopHeader').tabIndex=0;document.querySelector('.shopHeader').onkeydown=e=>{if(e.key==='Enter'||e.key===' ')ctx.openTool('settings');};}

 async function myProfile(body){if(!profile){showPage('setup');return;}const u=profile||{name:'',phone:''};body.innerHTML=`<h2>我的資料</h2><p class="sectionIntro">讓我們記得你的名字，也記得你的特別日子。</p>${profileFields(u)}<button id="mySave">儲存資料</button><p class="small">你更新的是自己提供的資料；店家保存的顧客檔案與備註由店家管理。重新加入後，可請店家協助核對資料。</p>`;$('pfGender').value=u.gender||'';const myPhoto=mountPhotoPicker($('pfAvatar'),{initial:u.avatar||'',max:220,budget:35000,round:true});task($('mySave'),async()=>{const data=validateProfile();data.avatar=myPhoto.value;const changed=Object.fromEntries(Object.entries(data).filter(([k,v])=>v!==profile?.[k]));if(!Object.keys(changed).length){toast('資料沒有變更');return;}if(demo){await store('users/'+auth.currentUser.uid,changed);profile={...profile,...data};}else{profile=await saveCustomerProfile({db,uid:auth.currentUser?.uid,changes:changed,doc,runTransaction,serverTimestamp});}updateChatName();toast('資料已儲存');});}
 function productPrice(p){return p.salePrice!==''&&p.salePrice!=null?`<del>NT$ ${esc(p.price)}</del> <strong>NT$ ${esc(p.salePrice)}</strong>`:p.price!==''&&p.price!=null?'NT$ '+esc(p.price):'價格洽詢';}
